package com.kaymlyn.planeteater.claude;

import com.kaymlyn.planeteater.simulation.physics.Orbit;
import com.kaymlyn.planeteater.simulation.physics.PhysicsConstants;
import com.kaymlyn.planeteater.simulation.physics.Vector3D;
import lombok.Getter;
import lombok.AllArgsConstructor;

/**
 * Calculates key points in an orbit
 * Provides position vectors for important orbital locations
 *
 * Generated by Claude (Sonnet 4.5)
 */
@Getter
@AllArgsConstructor
public class OrbitalPoints {

    private Vector3D periapsis;              // Closest point to central body
    private Vector3D apoapsis;               // Farthest point from central body
    private Vector3D semiMinorAxisPositive;  // +b direction (perpendicular to major axis)
    private Vector3D semiMinorAxisNegative;  // -b direction
    private Vector3D ascendingNode;          // Where orbit crosses ecliptic going up
    private Vector3D descendingNode;         // Where orbit crosses ecliptic going down

    /**
     * Calculate all key orbital points from orbital elements
     *
     * @param orbit Orbital elements
     * @return OrbitalPoints with all key positions
     */
    public static OrbitalPoints calculateOrbitalPoints(Orbit orbit) {
        double a = orbit.semiMajorAxis();
        double e = orbit.eccentricity();
        double i = orbit.inclination();
        double omega = orbit.ascendingNode();      // Longitude of ascending node (Ω)
        double w = orbit.periapsis();              // Argument of periapsis (ω)

        // Calculate key radii
        double r_peri = a * (1 - e);  // Periapsis radius
        double r_apo = a * (1 + e);   // Apoapsis radius
        double b = a * Math.sqrt(1 - e*e);  // Semi-minor axis length

        // Periapsis: at true anomaly = 0
        Vector3D periapsis = orbit.calculatePositionAtTrueAnomaly(0.0);

        // Apoapsis: at true anomaly = π
        Vector3D apoapsis = orbit.calculatePositionAtTrueAnomaly(Math.PI);

        // Semi-minor axis positive: at true anomaly = π/2
        Vector3D semiMinorPos = orbit.calculatePositionAtTrueAnomaly(Math.PI / 2.0);

        // Semi-minor axis negative: at true anomaly = 3π/2
        Vector3D semiMinorNeg = orbit.calculatePositionAtTrueAnomaly(3.0 * Math.PI / 2.0);

        // Ascending node: at true anomaly where orbit crosses ecliptic upward
        // This is at ν = -ω (in the orbital plane, before rotation)
        Vector3D ascendingNode;
        Vector3D descendingNode;

        if (Math.abs(i) > 1e-6) { // Only if orbit is inclined
            // Ascending node is at longitude Ω, in the ecliptic plane
            ascendingNode = new Vector3D(
                    Math.cos(omega),
                    Math.sin(omega),
                    0.0
            ).multiply(orbit.calculateRadiusAtTrueAnomaly(-w));

            // Descending node is 180° opposite
            descendingNode = new Vector3D(
                    Math.cos(omega + Math.PI),
                    Math.sin(omega + Math.PI),
                    0.0
            ).multiply(orbit.calculateRadiusAtTrueAnomaly(Math.PI - w));
        } else {
            // For non-inclined orbits, nodes are undefined - use zero vector
            ascendingNode = Vector3D.ZERO;
            descendingNode = Vector3D.ZERO;
        }

        return new OrbitalPoints(periapsis, apoapsis, semiMinorPos, semiMinorNeg,
                ascendingNode, descendingNode);
    }

    /**
     * Calculate time to reach a specific point from current position
     *
     * @param currentOrbit Current orbital elements
     * @param targetPoint Target position vector
     * @param centralMass Mass of central body
     * @return Time in seconds to reach target point
     */
    public static double calculateTimeToPoint(Orbit currentOrbit,
                                              Vector3D targetPoint,
                                              double centralMass) {
        double mu = PhysicsConstants.G * centralMass;
        double a = currentOrbit.semiMajorAxis();
        double e = currentOrbit.eccentricity();
        double nu_current = currentOrbit.trueAnomaly();

        // Find true anomaly of target point
        // This requires solving for ν given position
        double nu_target = calculateTrueAnomalyAtPosition(currentOrbit, targetPoint);

        // Convert to eccentric anomalies
        double E_current = trueToEccentricAnomaly(nu_current, e);
        double E_target = trueToEccentricAnomaly(nu_target, e);

        // Convert to mean anomalies
        double M_current = E_current - e * Math.sin(E_current);
        double M_target = E_target - e * Math.sin(E_target);

        // Mean anomaly difference
        double deltaM = M_target - M_current;

        // Normalize to [0, 2π]
        while (deltaM < 0) deltaM += 2 * Math.PI;
        while (deltaM >= 2 * Math.PI) deltaM -= 2 * Math.PI;

        // Mean motion: n = sqrt(μ/a³)
        double n = Math.sqrt(mu / Math.pow(a, 3));

        // Time = ΔM / n
        return deltaM / n;
    }

    /**
     * Calculate time to periapsis from current position
     */
    public static double calculateTimeToPeriapsis(Orbit currentOrbit, double centralMass) {
        OrbitalPoints points = calculateOrbitalPoints(currentOrbit);
        return calculateTimeToPoint(currentOrbit, points.getPeriapsis(), centralMass);
    }

    /**
     * Find true anomaly of a given position on the orbit
     */
    private static double calculateTrueAnomalyAtPosition(Orbit orbit, Vector3D position) {
        double a = orbit.semiMajorAxis();
        double e = orbit.eccentricity();
        double i = orbit.inclination();
        double omega = orbit.ascendingNode();
        double w = orbit.periapsis();

        // Transform position from 3D back to orbital plane
        double x = position.getX();
        double y = position.getY();
        double z = position.getZ();

        double cosO = Math.cos(omega);
        double sinO = Math.sin(omega);
        double cosi = Math.cos(i);
        double sini = Math.sin(i);
        double cosw = Math.cos(w);
        double sinw = Math.sin(w);

        // Inverse rotation (transpose of rotation matrix)
        double x_orbital = x * (cosO * cosw - sinO * sinw * cosi) +
                y * (sinO * cosw + cosO * sinw * cosi) +
                z * (sinw * sini);
        double y_orbital = -x * (cosO * sinw + sinO * cosw * cosi) -
                y * (sinO * sinw - cosO * cosw * cosi) +
                z * (cosw * sini);

        // True anomaly from position in orbital plane
        return Math.atan2(y_orbital, x_orbital);
    }

    /**
     * Convert true anomaly to eccentric anomaly
     */
    private static double trueToEccentricAnomaly(double nu, double e) {
        double cosE = (e + Math.cos(nu)) / (1 + e * Math.cos(nu));
        double sinE = Math.sqrt(1 - e*e) * Math.sin(nu) / (1 + e * Math.cos(nu));
        return Math.atan2(sinE, cosE);
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("=== Orbital Points ===\n");
        sb.append(String.format("Periapsis:  %s (%.3e m)\n", periapsis, periapsis.magnitude()));
        sb.append(String.format("Apoapsis:   %s (%.3e m)\n", apoapsis, apoapsis.magnitude()));
        sb.append(String.format("Semi-minor +: %s (%.3e m)\n", semiMinorAxisPositive,
                semiMinorAxisPositive.magnitude()));
        sb.append(String.format("Semi-minor -: %s (%.3e m)\n", semiMinorAxisNegative,
                semiMinorAxisNegative.magnitude()));

        if (!ascendingNode.equals(Vector3D.ZERO)) {
            sb.append(String.format("Ascending Node:  %s (%.3e m)\n", ascendingNode,
                    ascendingNode.magnitude()));
            sb.append(String.format("Descending Node: %s (%.3e m)\n", descendingNode,
                    descendingNode.magnitude()));
        } else {
            sb.append("Nodes: N/A (orbit not inclined)\n");
        }

        return sb.toString();
    }
}
